#!/usr/bin/env python3
"""Migrate ONLY untouched Switch 1 autogenerated Recommended baselines to FSR 1.

A change to general/recommended.json alone does NOT alter the snapshots
in each game JSON. This script is intentionally uniform (not fake per-game
optimization). Curated/user-modified games and NS2 profiles are never edited.
"""
import argparse
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
GAMES=ROOT/"games"
GENERAL=ROOT/"general/recommended.json"

def migrate(*,write:bool)->tuple[int,int]:
    expected=json.loads(GENERAL.read_text())["settings"]
    if expected["upscaling_filter"]!="fsr":
        raise ValueError("General Recommended must explicitly select FSR 1")
    old={**expected,"upscaling_filter":"bilinear"}
    rewritten=0
    skipped=0
    for path in sorted(GAMES.glob("*.json")):
        doc=json.loads(path.read_text())
        if doc.get("status")!="auto-baseline" or (
            doc.get("source_console")!="Nintendo Switch 1" or
            doc.get("generated",{}).get("generator")!="tools/sync_switch_games.py"
        ):
            skipped+=1
            continue
        entry=doc.get("profiles",{}).get("recommended",{})
        current=entry.get("settings",{})
        # Historical per-title records predate texture_anisotropy.
        # Only compare keys that were actually authored in this record;
        # never inject new fields or override later, title-specific choices.
        baseline={key:old[key] for key in current if key in old}
        expected_subset={key:expected[key] for key in current if key in expected}
        if current==expected_subset and current:
            continue
        if entry.get("profile_source")!="general/recommended.json" or (
            not current or set(current)-set(old) or current!=baseline
        ):
            skipped+=1
            continue
        if write:
            # Preserve every existing field, including manual metadata and
            # game references; only replace one scalar in the baseline.
            entry["settings"]["upscaling_filter"]="fsr"
            path.write_text(json.dumps(doc,ensure_ascii=False,indent=2)+"\n")
        rewritten+=1
    print(f"switch1_auto_recommended_fsr1_{'updated' if write else 'would_update'}={rewritten} untouched_or_custom={skipped}")
    return rewritten,skipped

if __name__=="__main__":
    ap=argparse.ArgumentParser()
    ap.add_argument("--write",action="store_true")
    args=ap.parse_args()
    migrate(write=args.write)
